#include <stdio.h>

struct Point { int x; int y; };

int main(void) {
    struct Point arr[3] = { {3,1}, {1,9}, {2,5} };
    struct Point *p;
    printf("unsorted:\n");
    for (p = arr; p < arr + 3; ++p) printf("  (%d,%d)\n", p->x, p->y);
    struct Point *max = &arr[0];
    for (p = arr + 1; p < arr + 3; ++p)
        if (p->x > max->x) max = p;
    printf("max x = (%d,%d)\n", max->x, max->y);
    return 0;
}
